881.     eprintln!("xcvrd-rs: initial sync complete; watching for change events");
882. 
883.     // Drive the CMIS datapath state machine once up-front so admin-up modules begin
884.     // leaving low power before the first DOM poll (a healthy module reaches READY within
885.     // a handful of ~1s serve passes). Skipped entirely under `--skip_cmis_mgr`
886.     // (`if not self.skip_cmis_mgr:`, xcvrd.py:1171).
887.     if !cfg.skip_cmis_mgr {
888.         cmis_datapath_sm(&platform, &state, &config, &mut ports, &media_env.g_optics, fast_reboot, host_tx_queue);
889.     }
890. 
891.     // SFF (non-CMIS) deterministic link bring-up, mirroring the CMIS pass. Gated on
892.     // `--enable_sff_mgr` (xcvrd.py:1150). Drives Tx_Disable / low-power / high-power-class for
893.     // SFF-8636/8472 modules per admin_status + host_tx_ready; a no-op on CMIS/absent ports.
894.     if cfg.enable_sff_mgr {
895.         sff_control(&platform, &state, &config, &ports, sff_state, admin_queue);
896.     }
897.     // Defer the first periodic DOM poll by one interval, mirroring the reference
898.     // `DomInfoUpdateTask.task_worker` (dom_mgr.py:296-298: "Adding
899.     // dom_info_update_periodic_secs to allow xcvrd to initialize ports before starting
900.     // the periodic update"). This is functionally important, not cosmetic: the latched
901.     // flag tables (TRANSCEIVER_DOM_FLAG / _STATUS_FLAG) must stay ABSENT until either the
902.     // first periodic poll or a link-change re-read
903.     // (`update_port_db_diagnostics_on_link_change`, serviced below). An immediate startup
904.     // poll would pre-publish `<flag>=False` for every present port, so the link-change
905.     // fast-recapture path could no longer be isolated from a stale poll value: a baseline
906.     // flap's `wait_until(<flag>=="False")` would return instantly on the stale row instead
907.     // of blocking on the flap's own re-read, letting that re-read fire later (with a
908.     // freshly-raised alarm) inside the pre-flap guard window. TRANSCEIVER_INFO/identity is
909.     // published synchronously by `sync_port` above, so the clean-baseline health check does
910.     // not depend on this first poll.
911.     let mut next_dom_time = Instant::now() + cfg.dom_update_interval;
912. 
913.     // Separate DOM temperature poll (`DomThermalInfoUpdateTask`, xcvrd.py:1183): only when
914.     // `--dom_temperature_poll_interval` is set, and its first poll fires immediately
915.     // (dom_mgr.py:542 `next_periodic_db_update_time = datetime.datetime.now()`).
916.     let mut next_thermal_time = cfg.dom_temperature_poll_interval.map(|_| Instant::now());
917. 
918.     // React to plug/unplug transitions. get_change_event blocks up to the timeout
919.     // and returns the set of physical ports whose presence changed. Each iteration
920.     // also services the EEPROM read-retry set on its ~60s cadence, drives CMIS
921.     // bring-up (~1s), watches APPL_DB for link flaps (fast flag re-capture), and
922.     // runs the periodic DOM poll on its ~60s cadence.
923.     loop {
924.         // Graceful shutdown (SIGTERM from `supervisorctl stop`): run the deinit teardown —
925.         // which preserves the TRANSCEIVER_STATUS pair on a warm/fast reboot so the live
926.         // datapath is not disrupted — then exit so run()'s retry loop does not respawn us.
927.         if SHUTDOWN_REQUESTED.load(Ordering::SeqCst) {
928.             eprintln!("xcvrd-rs: shutdown signal received; running deinit teardown");
929.             deinit_on_shutdown(&state, &ports);
930.             std::process::exit(0);
931.         }
932.         let ev = platform.get_change_event(1000)?;
933.         for (phys_str, code) in ev.sfp.iter() {
934.             let Ok(phys) = phys_str.parse::<usize>() else { continue };
935.             let Some(ctx) = ports.get_mut(&phys) else { continue };
936.             if code == sfp_status_helper::SFP_STATUS_INSERTED
937.                 || code == sfp_status_helper::SFP_STATUS_REMOVED
938.             {
939.                 // Plug-in ('1') or plug-out ('0'): (re)publish or tear down the port.
940.                 // A plug-in also clears any prior error state (sync_port rewrites
941.                 // TRANSCEIVER_STATUS_SW status/error), so recovering from an error is
942.                 // just the insert path.
943.                 let mut synced = sync_port(&platform, &state, phys, ctx);
944.                 // A just-inserted module whose identity EEPROM is not yet readable
945.                 // (present but the first read returned SFP_EEPROM_NOT_READY -> Ok(false)):
946.                 // pause briefly and re-read once before deferring to the slow
947.                 // RETRY_EEPROM_READING_INTERVAL set, mirroring xcvrd.py
948.                 // SfpStateUpdateTask.task_worker so a hot-plug repopulates
949.                 // TRANSCEIVER_INFO promptly (within T_FAST) instead of only on the next
950.                 // ~60s retry sweep. A plug-out always syncs Ok(true), so this pause only
951.                 // ever applies to a plug-in.
952.                 if matches!(synced, Ok(false)) {
953.                     sleep(TIME_FOR_SFP_READY);
954.                     synced = sync_port(&platform, &state, phys, ctx);
955.                 }
956.                 match synced {
957.                     Ok(true) => {
958.                         retry_eeprom_set.remove(&phys);
959.                         // Re(publish) media SI on the plug-in (idempotent via the DEFAULT
960.                         // guard); on a plug-out sync_port has reset the guard to DEFAULT so
961.                         // the next insertion re-publishes (test_..._default_to_notified).
962.                         // Skipped on a warm/fast reboot (xcvrd.py:584).
963.                         if !warm_fast_reboot {
964.                             publish_media_settings(&platform, &media_env, phys, &ctx.name);
965.                         }
966.                     }
967.                     Ok(false) => {
968.                         retry_eeprom_set.insert(phys);
969.                     }
970.                     Err(e) => eprintln!("xcvrd-rs: change sync {} (sfp {phys}) failed: {e}", ctx.name),
971.                 }
972.             } else {
973.                 // Any other change-event code is an SfpBase error bitmap: decode it
974.                 // into TRANSCEIVER_STATUS_SW.error and, for a blocking error, purge
975.                 // the (now out-of-date) DOM/hardware tables while keeping the static
976.                 // TRANSCEIVER_INFO (xcvrd.py:623-666).
977.                 if let Err(e) =
978.                     handle_sfp_error_event(&state, &ctx.name, code, ev.sfp_error.get(phys_str))
979.                 {
980.                     eprintln!("xcvrd-rs: error event {} (sfp {phys}) failed: {e}", ctx.name);
981.                 }
982.             }
983.         }
984. 
985.         // Reconcile CONFIG_DB logical-port add/remove (full per-port table teardown /
986.         // repopulation) BEFORE the per-port loops below, so a just-removed port is dropped from
