306. /// Python parser accepts.
307. fn daemon_usage() -> String {
308.     "usage: xcvrd-rs [-h] [--skip_cmis_mgr] [--enable_sff_mgr]\n\
309.      \x20               [--dom_temperature_poll_interval DOM_TEMPERATURE_POLL_INTERVAL]\n\
310.      \x20               [--dom_update_interval DOM_UPDATE_INTERVAL]\n"
