314. /// Consume the value for an option that takes one argument, supporting both the
315. /// `--flag value` and `--flag=value` forms (argparse accepts either). `idx` points at
316. /// the flag; on the space-separated form it is advanced past the consumed value.
317. fn take_option_value(
318.     flag: &str,
319.     inline: Option<String>,
320.     args: &[String],
321.     idx: &mut usize,
322. ) -> Result<String, ArgParseError> {
323.     if let Some(v) = inline {
324.         return Ok(v);
325.     }
326.     if *idx + 1 < args.len() {
327.         *idx += 1;
328.         return Ok(args[*idx].clone());
329.     }
330.     Err(ArgParseError::Invalid(format!(
331.         "argument {flag}: expected one argument"
332.     )))
