2886. fn publish_dom_flags(state: &DbConnector, sfp: &Sfp, port: &str) -> Result<(), Box<dyn Error>> {
2887.     let flags = match sfp.call_json("get_transceiver_dom_flags", ()) {
2888.         Ok(v) => v,
2889.         Err(_) => return Ok(()), // NotImplementedError / read fault → skip (log upstream)
2890.     };
2891.     let Some(flag_obj) = flags.as_object() else {
2892.         return Ok(());
2893.     };
2894.     if flag_obj.is_empty() {
2895.         return Ok(());
2896.     }
2897. 
2898.     let update_time = get_current_time();
2899.     // Previous flag values currently in STATE_DB (empty == not found == first publish).
2900.     let prev = hgetall_strings(state, &format!("{DOM_FLAG_TABLE}|{port}"))?;
2901.     update_flag_metadata_tables(
2902.         state,
2903.         port,
2904.         flag_obj,
2905.         &prev,
2906.         &update_time,
2907.         DOM_FLAG_CHANGE_COUNT_TABLE,
2908.         DOM_FLAG_SET_TIME_TABLE,
2909.         DOM_FLAG_CLEAR_TIME_TABLE,
2910.     )?;
2911. 
2912.     // Beautify (str() each value; no unit strip applies to boolean flag keys) and
2913.     // write TRANSCEIVER_DOM_FLAG with the trailing last_update_time.
2914.     let mut beautified = flag_obj.clone();
2915.     beautify_dom_info_dict(&mut beautified);
2916.     let key = format!("{DOM_FLAG_TABLE}|{port}");
2917.     for (field, value) in &beautified {
2918.         state.hset(&key, field, &CxxString::from(py_str(value).as_str()))?;
2919.     }
2920.     state.hset(&key, "last_update_time", &CxxString::from(update_time.as_str()))?;
2921.     Ok(())
