280. #[derive(Debug, Clone, Default, PartialEq, Eq)]
281. pub struct DaemonArgs {
282.     /// `--skip_cmis_mgr`: do not run the CMIS datapath state machine.
283.     pub skip_cmis_mgr: bool,
284.     /// `--enable_sff_mgr`: run the SFF (non-CMIS) deterministic link bring-up.
285.     pub enable_sff_mgr: bool,
286.     /// `--dom_temperature_poll_interval` (seconds): when set, run the separate DOM
287.     /// temperature poll (`DomThermalInfoUpdateTask`) at this cadence.
288.     pub dom_temperature_poll_interval: Option<i64>,
289.     /// `--dom_update_interval` (seconds): override the periodic DOM poll cadence
290.     /// (validated by [`resolve_dom_update_interval`]).
291.     pub dom_update_interval: Option<i64>,
292. }
293. 
294. /// Outcome of parsing the command line, mirroring how `argparse.parse_args()`
295. /// terminates the process: `-h/--help` prints usage and exits 0; any parse error
296. /// prints usage + a diagnostic to stderr and exits 2.
297. #[derive(Debug)]
298. enum ArgParseError {
299.     /// `-h`/`--help` was requested.
300.     HelpRequested,
301.     /// A malformed / unknown argument (argparse exit code 2).
302.     Invalid(String),
303. }
304. 
305. /// Usage text printed on `--help` or a parse error, matching the four options the
306. /// Python parser accepts.
307. fn daemon_usage() -> String {
308.     "usage: xcvrd-rs [-h] [--skip_cmis_mgr] [--enable_sff_mgr]\n\
309.      \x20               [--dom_temperature_poll_interval DOM_TEMPERATURE_POLL_INTERVAL]\n\
310.      \x20               [--dom_update_interval DOM_UPDATE_INTERVAL]\n"
311.         .to_string()
312. }
313. 
314. /// Consume the value for an option that takes one argument, supporting both the
315. /// `--flag value` and `--flag=value` forms (argparse accepts either). `idx` points at
316. /// the flag; on the space-separated form it is advanced past the consumed value.
317. fn take_option_value(
318.     flag: &str,
319.     inline: Option<String>,
320.     args: &[String],
321.     idx: &mut usize,
322. ) -> Result<String, ArgParseError> {
323.     if let Some(v) = inline {
324.         return Ok(v);
325.     }
326.     if *idx + 1 < args.len() {
327.         *idx += 1;
328.         return Ok(args[*idx].clone());
329.     }
330.     Err(ArgParseError::Invalid(format!(
331.         "argument {flag}: expected one argument"
332.     )))
333. }
334. 
335. /// Parse an option value as an `int`, mirroring argparse's `type=int` (which errors out
336. /// with exit code 2 on a non-integer).
337. fn parse_int_option(flag: &str, value: &str) -> Result<i64, ArgParseError> {
338.     value.trim().parse::<i64>().map_err(|_| {
339.         ArgParseError::Invalid(format!("argument {flag}: invalid int value: '{value}'"))
340.     })
341. }
342. 
343. /// Parse the daemon's arguments from the argv tail (i.e. everything after the program
344. /// name), faithfully reproducing the Python `argparse` parser in `xcvrd.py:main`. Kept
345. /// pure (no process exit, no globals) so it is unit-testable; `run` maps the error
346. /// variants onto argparse's exit behaviour.
347. fn parse_daemon_args(args: &[String]) -> Result<DaemonArgs, ArgParseError> {
348.     let mut out = DaemonArgs::default();
349.     let mut i = 0;
350.     while i < args.len() {
351.         let raw = args[i].clone();
352.         let (flag, inline) = match raw.split_once('=') {
353.             Some((f, v)) => (f.to_string(), Some(v.to_string())),
354.             None => (raw.clone(), None),
355.         };
356.         match flag.as_str() {
357.             "-h" | "--help" => return Err(ArgParseError::HelpRequested),
358.             "--skip_cmis_mgr" => {
359.                 if let Some(v) = inline {
360.                     return Err(ArgParseError::Invalid(format!(
361.                         "argument --skip_cmis_mgr: ignored explicit argument '{v}'"
362.                     )));
363.                 }
364.                 out.skip_cmis_mgr = true;
365.             }
366.             "--enable_sff_mgr" => {
367.                 if let Some(v) = inline {
368.                     return Err(ArgParseError::Invalid(format!(
369.                         "argument --enable_sff_mgr: ignored explicit argument '{v}'"
370.                     )));
371.                 }
372.                 out.enable_sff_mgr = true;
373.             }
374.             "--dom_temperature_poll_interval" => {
375.                 let v = take_option_value(&flag, inline, args, &mut i)?;
376.                 out.dom_temperature_poll_interval = Some(parse_int_option(&flag, &v)?);
377.             }
378.             "--dom_update_interval" => {
379.                 let v = take_option_value(&flag, inline, args, &mut i)?;
380.                 out.dom_update_interval = Some(parse_int_option(&flag, &v)?);
381.             }
382.             _ => {
383.                 return Err(ArgParseError::Invalid(format!(
384.                     "unrecognized arguments: {raw}"
385.                 )))
386.             }
387.         }
388.         i += 1;
389.     }
390.     Ok(out)
391. }
392. 
393. /// Resolve the effective DOM poll period from `--dom_update_interval`, mirroring
